  [review_count] INT NULL,
  [push_back_reason] NVARCHAR(MAX) NULL,
  [sent_to_cc] NVARCHAR(1000) NULL,
  [sent_at] DATETIME NULL,
  [sent_by] BIGINT NULL,
  [send_message] NVARCHAR(MAX) NULL,
